// @FIGURE_CODE_BEGIN
// ── Element spec (physics y → world +X, physics z → world +Y, physics x → world +Z)
// axis y / z / x      → thin cylinder shaft (r 0.018) + cone head (r 0.075, h 0.22), black
// dashed box (9 edges)→ LineSegments + LineDashedMaterial, gray #808080, dash .15 / gap .12
// A_x arrow           → cylinder (r .07) + cone (r .16, h .30) group, navy #1F4E79, along world +Z
// A_y arrow           → same, along world +X
// A_z arrow           → same, along world +Y
// ghost A_y / A_z     → same geometry, navy, opacity .3 (head-to-tail mode)
// resultant A         → cylinder + cone, red #C0504D (head #CF6A66), origin → (Ay, Az, Ax)
// far corner dot      → SphereGeometry(0.06), red
// labels              → addLabel HTML (italic/bold, combining vector arrows), screen-rotated

const UP = new THREE.Vector3(0, 1, 0);
const COL = { axis: 0x111111, blue: 0x1F4E79, red: 0xC0504D, redHead: 0xCF6A66, dash: 0x808080 };

scene.add(new THREE.AmbientLight(0xffffff, 0.78));
const _dl = new THREE.DirectionalLight(0xffffff, 0.45); _dl.position.set(6, 9, 7); scene.add(_dl);
const _dl2 = new THREE.DirectionalLight(0xffffff, 0.22); _dl2.position.set(-5, 3, -6); scene.add(_dl2);

const root = new THREE.Group();
scene.add(root);

/* ── arrow factory ─────────────────────────────────────────────── */
function makeArrow(color, shaftR, headLen, headR, opt = {}) {
  const transparent = opt.opacity !== undefined;
  const matS = new THREE.MeshLambertMaterial({
    color, transparent, opacity: opt.opacity ?? 1, depthWrite: !transparent
  });
  const matH = new THREE.MeshLambertMaterial({
    color: opt.headColor ?? color, transparent, opacity: opt.opacity ?? 1, depthWrite: !transparent
  });
  const g = new THREE.Group();
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, 1, 18), matS);
  const head = new THREE.Mesh(new THREE.ConeGeometry(headR, headLen, 24), matH);
  g.add(shaft); g.add(head);
  g.userData.set = (base, dir, len) => {
    if (!(len > 0.09)) { g.visible = false; return; }
    g.visible = true;
    g.position.copy(base);
    g.quaternion.setFromUnitVectors(UP, dir.clone().normalize());
    const hl = Math.min(headLen, len * 0.55);
    head.scale.set(1, hl / headLen, 1);
    const sl = Math.max(len - hl, 1e-3);
    shaft.scale.set(1, sl, 1);
    shaft.position.set(0, sl / 2, 0);
    head.position.set(0, sl + hl / 2, 0);
  };
  root.add(g);
  return g;
}

/* ── axes ──────────────────────────────────────────────────────── */
const axisY = makeArrow(COL.axis, 0.018, 0.22, 0.075);  // physics y → world +X
const axisZ = makeArrow(COL.axis, 0.018, 0.22, 0.075);  // physics z → world +Y
const axisX = makeArrow(COL.axis, 0.018, 0.22, 0.075);  // physics x → world +Z

/* ── dashed box ────────────────────────────────────────────────── */
const dashMat = new THREE.LineDashedMaterial({ color: COL.dash, dashSize: 0.15, gapSize: 0.12 });
const boxLines = new THREE.LineSegments(new THREE.BufferGeometry(), dashMat);
root.add(boxLines);

function rebuildBox(X, Y, Z) {
  const c = [];
  for (let i = 0; i < 8; i++) c.push(new THREE.Vector3((i & 1) ? X : 0, (i & 2) ? Y : 0, (i & 4) ? Z : 0));
  const pts = [];
  for (let i = 0; i < 8; i++) {
    if (i === 0) continue;               // skip the 3 edges lying on the axes (drawn as arrows)
    for (const b of [1, 2, 4]) {
      const j = i | b;
      if (j !== i) { pts.push(c[i], c[j]); }
    }
  }
  const g = new THREE.BufferGeometry().setFromPoints(pts);
  boxLines.geometry.dispose();
  boxLines.geometry = g;
  boxLines.computeLineDistances();
}

/* ── component + resultant arrows ──────────────────────────────── */
const armX = makeArrow(COL.blue, 0.07, 0.30, 0.16);
const armY = makeArrow(COL.blue, 0.07, 0.30, 0.16);
const armZ = makeArrow(COL.blue, 0.07, 0.30, 0.16);
const ghostY = makeArrow(COL.blue, 0.07, 0.30, 0.16, { opacity: 0.3 });
const ghostZ = makeArrow(COL.blue, 0.07, 0.30, 0.16, { opacity: 0.3 });
const armR = makeArrow(COL.red, 0.07, 0.32, 0.17, { headColor: COL.redHead });

const corner = new THREE.Mesh(
  new THREE.SphereGeometry(0.06, 16, 12),
  new THREE.MeshLambertMaterial({ color: COL.red })
);
root.add(corner);

registerInteractive(armR, {
  title: 'Resultant A⃗',
  tooltip: 'Resultant — body diagonal of the box',
  body: 'The red arrow is the body diagonal of the dashed box. Its magnitude is |A| = √(Ax² + Ay² + Az²), obtained from two nested right triangles: first in the base plane (√(Ax²+Ay²)), then with the vertical leg A_z.'
});
registerInteractive(armX, { title: 'A⃗ₓ = Aₓ î', tooltip: 'x-component (depth edge)', body: 'The projection of A⃗ onto the x-axis. It lies on the depth edge of the box, pointing out of the page toward the lower left.' });
registerInteractive(armY, { title: 'A⃗_y = A_y ĵ', tooltip: 'y-component (width edge)', body: 'The projection of A⃗ onto the y-axis, drawn on the width edge of the box.' });
registerInteractive(armZ, { title: 'A⃗_z = A_z k̂', tooltip: 'z-component (height edge)', body: 'The projection of A⃗ onto the z-axis, drawn on the vertical edge of the box. It lifts the resultant out of the xy-plane.' });

/* ── invisible framing box: keeps zoom fixed for the 5-unit worst case ── */
const frame = new THREE.Mesh(
  new THREE.BoxGeometry(1, 1, 1),
