);
root.add(corner);

/* ── right-triangle legs for the magnitude derivation ──────────── */
const triGeom = new THREE.BufferGeometry();
triGeom.setAttribute('position', new THREE.BufferAttribute(new Float32Array(12), 3));
const triLines = new THREE.LineSegments(triGeom, new THREE.LineBasicMaterial({ color: COL.tri }));
triLines.visible = false;
root.add(triLines);

registerInteractive(armR, {
  title: 'Resultant A⃗',
  tooltip: 'Resultant — body diagonal of the box',
  body: 'The red arrow is the body diagonal of the dashed box. Its magnitude is |A| = √(Ax² + Ay² + Az²), obtained from two nested right triangles: first in the base plane (√(Ax²+Ay²)), then with the vertical leg A_z.'
});
registerInteractive(armX, { title: 'A⃗ₓ = Aₓ î', tooltip: 'x-component (depth edge)', body: 'The projection of A⃗ onto the x-axis. It lies on the depth edge of the dashed box, pointing out of the page toward the lower left.' });
registerInteractive(armY, { title: 'A⃗_y = A_y ĵ', tooltip: 'y-component (width edge)', body: 'The projection of A⃗ onto the y-axis, drawn on the width edge of the box, running to the right.' });
registerInteractive(armZ, { title: 'A⃗_z = A_z k̂', tooltip: 'z-component (height edge)', body: 'The projection of A⃗ onto the z-axis, drawn on the vertical edge of the box. It lifts the resultant out of the xy-plane.' });

/* ── invisible framing proxy: keeps the zoom fixed across slider range ── */
const frame = new THREE.Mesh(
  new THREE.BoxGeometry(1, 1, 1),
  new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false })
);
frame.position.set(2.75, 2.75, 2.75);
frame.scale.set(6.5, 6.5, 6.5);
scene.add(frame);

/* ── DOM refs ──────────────────────────────────────────────────── */
const elAx = document.getElementById('ax');
const elAy = document.getElementById('ay');
const elAz = document.getElementById('az');
const elAxV = document.getElementById('axv');
const elAyV = document.getElementById('ayv');
const elAzV = document.getElementById('azv');
const elMag = document.getElementById('magOut');

/* ── labels ────────────────────────────────────────────────────── */
const VA = '<b><i>A</i></b>&#8407;';
function mkRot(html, opts, side, pad) {
  const e = addLabel('<span style="display:inline-block">' + html + '</span>',
    new THREE.Vector3(), Object.assign({ offset: [0, 0] }, opts));
  return { e, span: e.div.firstElementChild, a: new THREE.Vector3(), b: new THREE.Vector3(), side, pad };
}

const L = {
  axX: addLabel('<i>x</i>', new THREE.Vector3(), { bold: true, fontSize: '16px', offset: [-11, 13] }),
  axY: addLabel('<i>y</i>', new THREE.Vector3(), { bold: true, fontSize: '16px', offset: [13, 9] }),
  axZ: addLabel('<i>z</i>', new THREE.Vector3(), { bold: true, fontSize: '16px', offset: [-5, -13] }),
  cx: mkRot(VA + '<sub>x</sub> = <i>A</i><sub>x</sub><b>&#238;</b>',
    { color: '#1F4E79', fontSize: '14px' }, +1, 20),
  cy: mkRot(VA + '<sub>y</sub> = <i>A</i><sub>y</sub><b>&#309;</b>',
    { color: '#1F4E79', fontSize: '14px' }, -1, 20),
  cz: mkRot(VA + '<sub>z</sub> = <i>A</i><sub>z</sub><b>k&#770;</b>',
    { color: '#1F4E79', fontSize: '14px' }, -1, 20),
  res: mkRot(VA + ' = ' + VA + '<sub>x</sub> + ' + VA + '<sub>y</sub> + ' + VA + '<sub>z</sub>',
    { color: '#B03A36', fontSize: '14px' }, +1, 22),
  tri: mkRot('&radic;(<i>A</i><sub>x</sub>&sup2;+<i>A</i><sub>y</sub>&sup2;)',
    { color: '#147049', fontSize: '12px' }, +1, 16)
};
const ROT_KEYS = ['cx', 'cy', 'cz', 'res', 'tri'];

/* ── state + update ────────────────────────────────────────────── */
const S = { ax: 3, ay: 4, az: 4, mode: 'edges', t1: 0, t2: 0, tri: 0 };
let showTri = false;

function axLen(v) { return Math.max(v, 1.5) * 1.2 + 0.30; }

function update() {
  const { ax, ay, az } = S;
  const vX = new THREE.Vector3(ay, 0, 0);   // physics y  (screen right)
  const vY = new THREE.Vector3(0, az, 0);   // physics z  (screen up)
  const vZ = new THREE.Vector3(0, 0, ax);   // physics x  (toward viewer)
  const O = new THREE.Vector3(0, 0, 0);

  const LY = axLen(ay), LZ = axLen(az), LX = axLen(ax);
  axisY.userData.set(O, new THREE.Vector3(1, 0, 0), LY);
  axisZ.userData.set(O, new THREE.Vector3(0, 1, 0), LZ);
  axisX.userData.set(O, new THREE.Vector3(0, 0, 1), LX);

  rebuildBox(ay, az, ax);

  const baseY = vZ.clone().multiplyScalar(S.t1);                 // tip of A_x
  const baseZ = vZ.clone().add(vX).multiplyScalar(S.t2);         // tip of A_x + A_y

  armX.userData.set(O, new THREE.Vector3(0, 0, 1), ax);
  armY.userData.set(baseY, new THREE.Vector3(1, 0, 0), ay);
  armZ.userData.set(baseZ, new THREE.Vector3(0, 1, 0), az);

  ghostY.userData.set(O, new THREE.Vector3(1, 0, 0), ay);
  ghostZ.userData.set(O, new THREE.Vector3(0, 1, 0), az);
  ghostY.visible = ghostY.visible && S.t1 > 0.04;
  ghostZ.visible = ghostZ.visible && S.t2 > 0.04;

  const R = new THREE.Vector3(ay, az, ax);
  const mag = R.length();
  armR.userData.set(O, mag > 1e-6 ? R : new THREE.Vector3(0, 0, 1), mag);
  corner.position.copy(R);
  corner.visible = mag > 0.09;

  // right-triangle legs: O → (Ay,0,Ax) → (Ay,Az,Ax)
  const P = new THREE.Vector3(ay, 0, ax);
  const tp = triGeom.attributes.position;
  tp.setXYZ(0, 0, 0, 0); tp.setXYZ(1, P.x, P.y, P.z);
  tp.setXYZ(2, P.x, P.y, P.z); tp.setXYZ(3, R.x, R.y, R.z);
  tp.needsUpdate = true;
  triGeom.computeBoundingSphere();
  triLines.visible = showTri && mag > 0.09;

  // label anchors
  L.axX.pos.set(0, 0, LX + 0.28);
  L.axY.pos.set(LY + 0.28, 0, 0);
  L.axZ.pos.set(0, LZ + 0.30, 0);

  L.cx.e.pos.copy(vZ).multiplyScalar(0.55);
  L.cx.a.set(0, 0, 0); L.cx.b.copy(vZ);

  L.cy.e.pos.copy(baseY).addScaledVector(vX, 0.58);
  L.cy.a.copy(baseY); L.cy.b.copy(baseY).add(vX);

  L.cz.e.pos.copy(baseZ).addScaledVector(vY, 0.55);
  L.cz.a.copy(baseZ); L.cz.b.copy(baseZ).add(vY);

  L.res.e.pos.copy(R).multiplyScalar(0.48);
  L.res.a.set(0, 0, 0); L.res.b.copy(R);

  L.tri.e.pos.copy(P).multiplyScalar(0.55);
  L.tri.a.set(0, 0, 0); L.tri.b.copy(P);

  L.cx.e.div.style.opacity = ax > 0.09 ? 1 : 0;
  L.cy.e.div.style.opacity = ay > 0.09 ? 1 : 0;
  L.cz.e.div.style.opacity = az > 0.09 ? 1 : 0;
  L.res.e.div.style.opacity = mag > 0.09 ? 1 : 0;
  L.tri.e.div.style.opacity = (showTri && P.length() > 0.2) ? 1 : 0;

  elAx.value = ax.toFixed(1); elAy.value = ay.toFixed(1); elAz.value = az.toFixed(1);
  elAxV.textContent = ax.toFixed(1);
  elAyV.textContent = ay.toFixed(1);
  elAzV.textContent = az.toFixed(1);
  elMag.textContent = '|A| = ' + mag.toFixed(2);
}

update();

/* ── camera (AFTER geometry) ───────────────────────────────────────
   Source-matched axonometric pose: the y-axis runs almost horizontally to the
   right (≈4° drop), the x-axis recedes to the lower-left at ≈44°. Solving the
   axis-angle inversion gives azimuth ≈75°, elevation ≈15° — which keeps the red
   body diagonal well off the view axis so it stays long on screen.          */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 4, z: 44 },
  rollDeg: 0,
  heightFraction: 0.75
});
controls.minPolarAngle = 0.10;
controls.maxPolarAngle = Math.PI * 0.49;
controls.minZoom = HOME_ZOOM * 0.6;
controls.maxZoom = HOME_ZOOM * 3.0;
document.getElementById('btnReset').style.display = '';

/* ── screen-space label rotation + perpendicular offset ────────── */
const _q1 = new THREE.Vector3(), _q2 = new THREE.Vector3();
function updateLabelDecor() {
  const w = canvas.clientWidth, h = canvas.clientHeight;
  for (const k of ROT_KEYS) {
    const o = L[k];
    _q1.copy(o.a).project(camera); _q2.copy(o.b).project(camera);
    let dx = (_q2.x - _q1.x) * w * 0.5;
    let dy = -(_q2.y - _q1.y) * h * 0.5;          // +dy = downward in pixels
    const len = Math.hypot(dx, dy);
    if (len < 1e-6) { dx = 1; dy = 0; } else { dx /= len; dy /= len; }
    let deg = Math.atan2(dy, dx) * 180 / Math.PI;
    if (deg > 90) deg -= 180;
    if (deg < -90) deg += 180;
    o.span.style.transform = 'rotate(' + deg.toFixed(1) + 'deg)';
    o.e.offset[0] = -dy * o.side * o.pad;
    o.e.offset[1] = dx * o.side * o.pad;
  }
}

/* ── tween engine ──────────────────────────────────────────────── */
const _tw = [];
let _dirty = true;
function tween(key, to, dur, delay) {
  for (let i = _tw.length - 1; i >= 0; i--) if (_tw[i].key === key) _tw.splice(i, 1);
  _tw.push({ key, from: S[key], to, t0: performance.now() + (delay || 0) * 1000, dur: dur * 1000 });
}
function setNow(key, v) {
  for (let i = _tw.length - 1; i >= 0; i--) if (_tw[i].key === key) _tw.splice(i, 1);
  S[key] = v; _dirty = true;
}
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  for (let i = _tw.length - 1; i >= 0; i--) {
    const t = _tw[i];
    if (now < t.t0) continue;
    let u = (now - t.t0) / t.dur;
    if (u >= 1) { u = 1; _tw.splice(i, 1); }
    const e = u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
    S[t.key] = t.from + (t.to - t.from) * e;
    _dirty = true;
  }
  if (_dirty) { update(); _dirty = false; }
  updateLabelDecor();
}

/* ── controls wiring ───────────────────────────────────────────── */
function markPreset(name) {
  document.querySelectorAll('#presetCase button').forEach(b =>
    b.classList.toggle('active', b.dataset.p === name));
}
function syncPresetFromState() {
  if (Math.abs(S.ay) < 0.05 && Math.abs(S.az) < 0.05) markPreset('x only');
  else if (Math.abs(S.az) < 0.05) markPreset('xy-plane');
  else markPreset('full xyz');
}

[['ax', elAx], ['ay', elAy], ['az', elAz]].forEach(([k, el]) => {
  el.addEventListener('input', () => { setNow(k, parseFloat(el.value)); syncPresetFromState(); });
});

document.querySelectorAll('#presetCase button').forEach(btn => {
  btn.addEventListener('click', () => {
    const p = btn.dataset.p;
    const v = p === 'x only' ? [3, 0, 0] : p === 'xy-plane' ? [3, 4, 0] : [3, 4, 4];
    tween('ax', v[0], 0.7); tween('ay', v[1], 0.7); tween('az', v[2], 0.7);
    markPreset(p);
  });
});

function setMode(m, restart) {
  S.mode = m;
  document.querySelectorAll('#buildMode button').forEach(b =>
    b.classList.toggle('active', b.dataset.m === m));
  if (m === 'chain') {
    if (restart) { setNow('t1', 0); setNow('t2', 0); }
    tween('t1', 1, 1.2, 0);
    tween('t2', 1, 1.2, 1.2);
  } else {
    tween('t2', 0, 0.8, 0);
    tween('t1', 0, 0.8, 0.3);
  }
}
document.querySelectorAll('#buildMode button').forEach(b => {
  b.addEventListener('click', () => setMode(b.dataset.m, b.dataset.m === 'chain'));
});
document.getElementById('playBuild').addEventListener('click', () => setMode('chain', true));

const triBtn = document.getElementById('triToggle');
triBtn.addEventListener('click', () => {
  showTri = !showTri;
  triBtn.classList.toggle('active', showTri);
  triBtn.textContent = (showTri ? '△ Hide' : '△ Show') + ' magnitude right triangles';
  _dirty = true;
});

/* ── guided demo ───────────────────────────────────────────────── */
const STEPS = [
  {
    title: 'One component only',
    narr: 'With A_y = A_z = 0 the vector lies flat along the x-axis; the box has collapsed to a single segment and the red resultant coincides with the blue A_x arrow.',
    preset: 'x only', v: [3, 0, 0], mode: 'edges'
  },
  {
    title: 'Two components — a planar vector',
    narr: 'Add a y-component and the box becomes a flat rectangle in the xy-plane. The red arrow is now the rectangle\'s diagonal, with magnitude √(Ax²+Ay²).',
    preset: 'xy-plane', v: [3, 4, 0], mode: 'edges'
  },
  {
    title: 'Three components — the full 3D vector',
    narr: 'Raising A_z inflates the rectangle into the dashed box of the original figure; the red arrow is its body diagonal and its length is √(Ax²+Ay²+Az²).',
    preset: 'full xyz', v: [3, 4, 4], mode: 'edges'
  },
  {
    title: 'Head-to-tail equivalence',
    narr: 'A_y is re-drawn from the tip of A_x and A_z from the tip of their sum. The chain ends exactly at the red arrowhead, proving A⃗ = A⃗x + A⃗y + A⃗z.',
    preset: 'full xyz', v: [3, 4, 4], mode: 'chain'
  },
  {
    title: 'Sweep a component',
    narr: 'Drag A_z on its own: the box height, the blue z-arrow and the red diagonal all update together, so magnitude and elevation angle respond to a single component.',
    preset: 'full xyz', v: [3, 4, 1.5], mode: 'edges'
  }
];
let stepIdx = 2;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepNarr').textContent = s.narr;
  tween('ax', s.v[0], 0.8); tween('ay', s.v[1], 0.8); tween('az', s.v[2], 0.8);
  markPreset(s.preset);
  setMode(s.mode, s.mode === 'chain');
}
document.getElementById('nextStep').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('prevStep').addEventListener('click', () => goToStep(stepIdx - 1));

/* ── go ────────────────────────────────────────────────────────── */
updateLabelDecor();
tick();
